  [1649] = { "Il Tome of Valor", "Parla con Duthorian Rall, a Stormwind.", nil, nil, nil, 0xdaebf666, 0x0f3ca705, nil, nil, nil, "..mmm" },
  [1650] = { "Il Tome of Valor", nil, nil, nil, nil, 0xdaebf666, nil, nil, nil, nil, ".mmmm" },
  [1651] = { "Il Tome of Valor", "Difendi Daphne Stilwell dall'attacco dei Defias.\n\nPer riuscire, nessuno dei vostri spiriti deve lasciare le proprie spoglie mortali.\n\nQuando ci sarai <riuscito/riuscita>, parla di nuovo con Daphne Stilwell.", "Ora, scommetto che torneranno presto, quindi preparati.\n\nHo un fucile in casa. Lo prendo e sarò pronta ad aiutarti, ma per lo più dovrai cavartela da <solo/sola>.\n\nNon ho idea di quanti ne manderanno, ma di sicuro saranno più dei pochi che hanno mandato prima.\n\nChiedi alla Luce tutte le benedizioni che puoi, perché... hai sentito? Credo che stiano arrivando.\n\nResistiamo vicino alla casa!", "Resistiamo vicino alla casa!", "Ce l'abbiamo fatta, {name}! Grazie per l'aiuto. Sei <stato/stata> davvero <straordinario/straordinaria> là fuori. Non avrei mai pensato che un paladino potesse tenere testa a tanti nemici insieme.\n\nHai davvero dimostrato coraggio contro forze soverchianti.", 0xdaebf666, 0x891ebe27, 0xa90e2959, 0x52f37378, 0x0f46273c, "....." },
  [1652] = { "Il Tome of Valor", "Parla con Duthorian Rall, a Stormwind.", nil, nil, nil, 0xdaebf666, 0x0f3ca705, nil, nil, nil, "..mmm" },
  [1661] = { nil, "Parla con Duthorian Rall, a Stormwind.", nil, nil, nil, nil, 0x0f3ca705, nil, nil, nil, "m.mmm" },
  [1667] = { nil, "Recupera la Haggard's Badge dall'accampamento di Dead-tooth Jack e torna da Marshal Haggard.", "Ti manda Burlguard, eh? Sì, ho delle armi di scorta qui, ma prima ho un compito per te...\n\nTempo fa un furfante dei Defias, Dead-tooth Jack, mi ha imbrogliato. Era buio, lui indossava una tabarda di Stormwind e l'ho scambiato per Marshal Dughan. Mi ha detto che gli serviva il mio vecchio distintivo da maresciallo di Stormwind e gliel'ho dato... poi è scoppiato a ridere ed è scappato prima che potessi prenderlo!\n\nRiprendi il mio distintivo! Probabilmente Dead-tooth Jack lo tiene nascosto nel suo accampamento, a sud.", "Hai il mio distintivo? Non voglio nemmeno pensare ai guai che Dead-tooth Jack potrebbe combinare con quello.", "Grande, l'hai trovato! Temevo fosse perduto per sempre, usato dai Defias per spacciarsi per un ufficiale di Stormwind. Be', ora non succederà, grazie a te.\n\nEcco alcune armi che usavo quando ero maresciallo. Le ho tenute in ottimo stato: scegli pure!", nil, 0xe3968aa6, 0x35913d6c, 0x0dd5019b, 0xaa14a96f, "m...." },
  [1685] = { "La convocazione di Gakin", "Fai rapporto a Gakin the Darkbinder, nel Mage Quarter di Stormwind.", "Non va sempre così? Ti ho cercato tutto il giorno senza trovarti, e ora che non me l'aspetto, mi vieni incontro.\n\nHo perso abbastanza tempo a cercarti, quindi non ti trattengo oltre. Master Gakin ti ha convocato per un addestramento supplementare. Se fossi in te, andrei da lui il prima possibile.\n\nLo trovi nel seminterrato della taverna Slaughtered Lamb. A proposito, forse è meglio che quel posto resti un segreto. Non vogliamo che se ne parli in giro.", nil, "Era ora che ti facessi vedere. Anche se forse avrei dovuto mandare qualcuno più capace di Remen a cercarti.\n\nNon importa.\n\nSei <rimasto/rimasta> troppo a lungo senza addestramento, e uno stregone senza addestramento difficilmente terrà la testa sulle spalle a lungo.", 0xafbad200, 0xd830dab8, 0x7de17495, nil, 0x9da53ed7, "...m." },
  [1699] = { "La Rethban Gauntlet", "Entra nelle Rethban Caverns, raggiungi il primo bivio e torna da Yorus Barleybrew entro il tempo concesso.\n\nNon devi morire né liberare il tuo spirito.", "La mia sfida la chiamo Rethban Gauntlet. Per superare la prova devi solo entrare nelle Rethban Caverns, arrivare al primo bivio e tornare qui. Facile! Solo che ci sono un paio di intoppi...\n\nDevi tornare entro un'ora.\n\nLungo la strada ci sono mucchi di Redridge Gnolls.\n\nPrima di partire, devi bere un sorso della bevanda tipica della mia famiglia: il Barleybrew Scalder!\n\nAllora, che ne dici? Le Rethban Caverns sono sulle colline a nord di Lakeshire. Sei <pronto/pronta> per la Rethban Gauntlet?", "Il tempo stringe, {name}. Se fossi in te, mi sbrigherei...", "Ce l'hai fatta! Ben fatto! Tre urrà per {name}!", 0xd10a48fe, 0xa8194546, 0xfd08c428, 0x9b73f4f5, 0x9fe48580, "....." },
  [1702] = { "Il fabbro di scudi", "Porta il Cask of Scalder a Furen Longbeard.", "Hai proprio dimostrato di che pasta sei <fatto/fatta> quando hai corso la Rethban Gauntlet, {name}. E io sono di parola. Ti darò la ricompensa che ti ho promesso...\n\nSolo che è a Stormwind.\n\nParla con il mio amico Furen Longbeard, nel Dwarven District di Stormwind. È il miglior fabbro di scudi che incontrerai mai, e mi deve un grosso favore.\n\nTieni, porta a Furen questa botticella di Barleybrew Scalder e chiedigli uno scudo. Te ne darà uno bello.", "Salve! Che siccità, non trovi?", "Ah, Barleybrew Scalder. Roba ottima! Quindi sei <stato/stata> da Yorus, eh?\n\nPosso darti uno scudo, sì! Non ne troverai uno migliore, parola mia!", 0x798b8e48, 0xa9d5c007, 0x121a2fd8, 0x9fc39f0a, 0x9c18ee37, "....." },
